NetworkPacket deserialize_packet(const std::span<const uint8_t> buffer) {
    // Create a mutable span for the buffer adaptor (read operations don't modify underlying data)
    auto mutable_buffer = std::span<uint8_t>(const_cast<uint8_t*>(buffer.data()), buffer.size());
    hexi::pmc::buffer_adaptor<std::span<uint8_t>> buf_adaptor(mutable_buffer);
    hexi::binary_stream<decltype(buf_adaptor)> stream(buf_adaptor);

    NetworkPacket packet;

    // Read the packet_id
    stream >> packet.packet_id;

    // Read the username using the length prefix
    stream >> packet.username;

    // Read the score count, then read the scores vector using prefixed adaptor
