struct PacketHeader {
    uint8_t version;
    uint8_t flags;
    uint16_t packet_id;
};

PacketHeader read_packet_header(const std::span<const uint8_t> buffer) {
    // Use zero-copy by directly interpreting the buffer memory as PacketHeader
    // This creates a span view over the header structure
    PacketHeader header;
    if (buffer.size() >= sizeof(PacketHeader)) {
        // Zero-copy read: directly copy bytes from buffer to header structure
        std::memcpy(&header, buffer.data(), sizeof(PacketHeader));
    }
    return header;
}

std::string_view read_message_until_delimiter(const std::span<const uint8_t> buffer) {
    // Use zero-copy by creating a string_view that points directly to buffer memory
    // Find the null terminator position
    size_t length = 0;
    while (length < buffer.size() && buffer[length] != '\0') {
        ++length;
    }

    // Return a string_view pointing directly to the buffer (zero-copy)
    return std::string_view(
        reinterpret_cast<const char*>(buffer.data()),
        length
    );
}
