struct DataResult {
    uint8_t data_type;
    std::vector<uint32_t> int_items;
    std::vector<float> float_items;
};

DataResult preview_and_read_data(const std::span<const uint8_t> buffer) {
    DataResult result;

    // Create a mutable buffer from the input span
    std::vector<uint8_t> buffer_vec(buffer.begin(), buffer.end());

    // Create buffer_adaptor for preview and reading
    hexi::buffer_adaptor adaptor(buffer_vec);

    // PREVIEW PHASE: Preview the first byte (data_type) without advancing the read pointer
    uint8_t preview_type;
    adaptor.copy(&preview_type);

    // Check available data size (minimum: data_type + item_count)
    constexpr std::size_t min_header_size = sizeof(uint8_t) + sizeof(uint32_t);
    if (adaptor.size() < min_header_size) {
        return result; // Not enough data for header
    }

    // READ PHASE: Now actually read the data using binary_stream
    hexi::pmc::buffer pmc_buffer;
    pmc_buffer.assign(buffer_vec.begin(), buffer_vec.end());
    hexi::pmc::binary_stream stream(pmc_buffer);

    // Read data_type
    stream.read(&result.data_type, sizeof(uint8_t));

    // Read item_count
    uint32_t item_count;
    stream.read(&item_count, sizeof(uint32_t));

    // Read items based on the data type
    if (result.data_type == 0) {
        // Type 0: integers (uint32_t)
        result.int_items.resize(item_count);
        for (uint32_t i = 0; i < item_count; ++i) {
            stream.read(&result.int_items[i], sizeof(uint32_t));
        }
    } else if (result.data_type == 1) {
        // Type 1: floats
        result.float_items.resize(item_count);
        for (uint32_t i = 0; i < item_count; ++i) {
            stream.read(&result.float_items[i], sizeof(float));
        }
    }

    return result;
}
