#include <hexi/hexi.h>
#include <vector>
#include <cstdint>

bool write_data_with_check(std::vector<uint8_t>& buffer, uint32_t header, const std::vector<uint32_t>& items) {
    // Create buffer adaptor with init_empty to start writing from beginning
    hexi::buffer_adaptor<std::vector<uint8_t>> adaptor(buffer, hexi::init_empty);

    // Calculate required space: header (4 bytes) + item count (4 bytes) + items data
    const size_t required_space = sizeof(uint32_t) + sizeof(uint32_t) + items.size() * sizeof(uint32_t);

    // Check available space
    if (adaptor.free() < required_space) {
        return false;
    }

    // Get the write pointer
    [[maybe_unused]] auto* write_ptr = adaptor.write_ptr();

    // Create binary stream with no_throw exception handling
    hexi::binary_stream<hexi::buffer_adaptor<std::vector<uint8_t>>, hexi::no_throw_t> stream(adaptor);

    // Write header
    stream << header;

    // Write container data (uses write_container internally via prefixed)
    stream << hexi::prefixed(items);

    // Return true if write was successful, false otherwise
    return stream.good();
}
