MessagePacket read_header_and_message(const std::span<const uint8_t> buffer) {
    // Create a mutable span for the buffer adaptor
    // (const_cast is safe here since we're only reading, not modifying the data)
    auto mutable_span = std::span<uint8_t>(
        const_cast<uint8_t*>(buffer.data()),
        buffer.size()
    );

    // Create buffer adaptor
    hexi::pmc::buffer_adaptor<std::span<uint8_t>> adaptor(mutable_span);

    // Read the header using buffer_adaptor's read method
    uint32_t header;
    adaptor.read(&header, sizeof(uint32_t));

    // Create binary stream from the adaptor
    hexi::binary_stream stream(adaptor);

    // Use binary_stream's view method to read null-terminated message
    std::string_view message = stream.view();

    return MessagePacket{header, message};
}
