#include <hexi/hexi.h>
#include <hexi/endian.h>
#include <hexi/pmc/binary_stream.h>
#include <hexi/pmc/buffer_adaptor.h>
#include <vector>
#include <cstdint>
#include <string>

struct MeasurementData {
    uint32_t sensor_id;
    std::vector<float> temperatures;
    double pressure;

    void serialise(auto& adaptor) const {
        // Write sensor_id directly
        adaptor << sensor_id;

        // Write temperature count
        adaptor << static_cast<uint32_t>(temperatures.size());

        // Convert each temperature from native to little-endian and write
        for (const auto& temp : temperatures) {
            float converted = hexi::endian::conditional_reverse(temp, std::endian::native, std::endian::little);
            adaptor.write(&converted, sizeof(converted));
        }

        // Convert pressure from native to little-endian and write
        double converted_pressure = hexi::endian::conditional_reverse(pressure, std::endian::native, std::endian::little);
        adaptor.write(&converted_pressure, sizeof(converted_pressure));
    }

    void serialise(auto& adaptor) {
        // Read sensor_id directly
        adaptor >> sensor_id;

        // Read temperature count
        uint32_t count;
        adaptor >> count;

        // Read each temperature and convert from little-endian to native in-place
        temperatures.resize(count);
        for (auto& temp : temperatures) {
            adaptor.get(&temp, 1);
            hexi::endian::little_to_native_inplace(temp);
        }

        // Read pressure and convert from little-endian to native in-place
        adaptor.get(&pressure, 1);
        hexi::endian::little_to_native_inplace(pressure);
    }
};

std::vector<uint8_t> serialize_measurement_data(const MeasurementData& data) {
    std::vector<uint8_t> buffer;
    hexi::pmc::buffer_adaptor<std::vector<uint8_t>> adaptor(buffer, hexi::pmc::init_empty);
    hexi::pmc::binary_stream stream(adaptor);
    stream.serialise(data);
    return buffer;
}

MeasurementData deserialize_measurement_data(const std::span<const uint8_t> buffer) {
    MeasurementData data;
    std::vector<uint8_t> vec(buffer.begin(), buffer.end());
    hexi::pmc::buffer_adaptor<std::vector<uint8_t>> adaptor(vec);
    hexi::pmc::binary_stream stream(adaptor);
    stream.deserialise(data);
    return data;
}

struct SensorInfo {
    uint32_t sensor_id;
    std::string_view sensor_name;
};

SensorInfo extract_sensor_info(const std::span<const uint8_t> buffer) {
    std::vector<uint8_t> vec(buffer.begin(), buffer.end());
    hexi::pmc::buffer_adaptor<std::vector<uint8_t>> adaptor(vec);
    hexi::pmc::binary_stream stream(adaptor);

    SensorInfo info;
    // Use view to extract null-terminated sensor name string
    info.sensor_name = stream.view();

    // enforce_read_bounds is called internally by the stream before reading
    // Read the sensor_id directly
    stream >> info.sensor_id;

    // Skip the remaining data
    if (stream.size() > 0) {
        stream.skip(stream.size());
    }

    return info;
}
